1	import { getDb } from '../store/db'
2	import {
3	  CLIP_HARD_CAP_BYTES,
4	  CLIP_SOFT_WARN_BYTES,
5	  SUPPORTED_CLIP_MIME_TYPES,
6	  type AddClipResult,
7	  type ClipRecord,
8	} from './types'
9	
10	function mintClipId(now: number): string {
11	  return `clip-${now.toString(36)}-${Math.random().toString(36).slice(2, 9)}`
12	}
13	
14	function isQuotaError(err: unknown): boolean {
15	  return (
16	    err instanceof DOMException &&
17	    (err.name === 'QuotaExceededError' || err.code === 22)
18	  )
19	}
20	
21	function errorMessage(err: unknown): string {
22	  if (err instanceof Error) return err.message
23	  return String(err)
24	}
25	
26	export async function addClip(
27	  file: File,
28	  opts: { durationMs: number },
29	): Promise<AddClipResult> {
30	  const db = getDb()
31	  if (!db) {
32	    return {
33	      ok: false,
34	      reason: 'storage-error',
35	      message: 'Database is unavailable.',
36	    }
37	  }
38	
39	  if (!SUPPORTED_CLIP_MIME_TYPES.includes(file.type)) {
40	    return {
41	      ok: false,
42	      reason: 'unsupported-type',
43	      message: `File type ${file.type || '(unknown)'} is not supported. Use .mp4.`,
44	    }
45	  }
46	
47	  if (file.size > CLIP_HARD_CAP_BYTES) {
48	    const mb = Math.round(file.size / 1024 / 1024)
49	    return {
50	      ok: false,
51	      reason: 'too-large',
52	      message: `Clip is ${mb} MB; the per-clip limit is ${CLIP_HARD_CAP_BYTES / 1024 / 1024} MB.`,
53	    }
54	  }
55	
56	  const clip: ClipRecord = {
57	    id: mintClipId(Date.now()),
58	    name: file.name,
59	    mimeType: file.type,
60	    durationMs: Math.max(0, Math.round(opts.durationMs)),
61	    sizeBytes: file.size,
62	    importedAt: Date.now(),
63	    blob: file,
64	  }
65	
66	  try {
67	    await db.clips.put(clip)
68	  } catch (err) {
69	    if (isQuotaError(err)) {
70	      return {
71	        ok: false,
72	        reason: 'quota',
73	        message:
74	          'Browser storage quota exceeded. Delete a clip before importing more.',
75	      }
76	    }
77	    return { ok: false, reason: 'storage-error', message: errorMessage(err) }
78	  }
79	
80	  return { ok: true, clip }
81	}
82	
83	export async function listClips(): Promise<ClipRecord[]> {
84	  const db = getDb()
85	  if (!db) return []
86	  try {
87	    return await db.clips.orderBy('importedAt').reverse().toArray()
88	  } catch {
89	    return []
90	  }
91	}
92	
93	export async function deleteClip(id: string): Promise<void> {
94	  const db = getDb()
95	  if (!db) return
96	  try {
97	    await db.clips.delete(id)
98	  } catch {
99	    /* leave the row in place; UI can retry */
100	  }
101	}
102	
103	export interface QuotaEstimate {
104	  usageBytes: number
105	  quotaBytes: number
106	  /** 0..1; quotaBytes can be 0 on browsers that decline to report. */
107	  percent: number
108	}
