import Dexie, { type EntityTable } from 'dexie'
import type { RepRecord, SessionRecord } from '../engine/types'
import type { SettingsRecord } from './settings-types'
import type { ProfileRecord } from './profiles'
import type { ClipRecord } from '../clipmode/types'

export class ReactorDB extends Dexie {
  sessions!: EntityTable<SessionRecord, 'id'>
  reps!: EntityTable<RepRecord, 'id'>
  settings!: EntityTable<SettingsRecord, 'id'>
  profiles!: EntityTable<ProfileRecord, 'id'>
  clips!: EntityTable<ClipRecord, 'id'>

  constructor() {
    super('pointfight-reactor')
    this.version(1).stores({
      sessions: 'id, startedAt',
      reps: 'id, sessionId, cueId',
    })
    this.version(2).stores({
      sessions: 'id, startedAt',
      reps: 'id, sessionId, cueId',
      settings: 'id',
    })
    this.version(3).stores({
      sessions: 'id, startedAt',
      reps: 'id, sessionId, cueId',
      settings: 'id',
      profiles: 'id, createdAt',
    })
    // Phase 6.1: clip library. `clipId` index on reps lights up in 6.3 when
    // RepRecord gains the field; pre-v4 reps remain readable and simply
    // never match `where('clipId').equals(...)` queries.
    this.version(4).stores({
      sessions: 'id, startedAt',
      reps: 'id, sessionId, cueId, clipId',
      settings: 'id',
      profiles: 'id, createdAt',
      clips: 'id, importedAt',
    })
  }
}

let _db: ReactorDB | null = null
let _openError: Error | null = null

export function getDb(): ReactorDB | null {
  if (_db) return _db
  if (_openError) return null
  try {
    _db = new ReactorDB()
    return _db
  } catch (err) {
    _openError = err instanceof Error ? err : new Error(String(err))
    return null
  }
}

export function getDbError(): Error | null {
  return _openError
}

export async function saveSession(session: SessionRecord): Promise<void> {
  const db = getDb()
  if (!db) return
  try {
    await db.sessions.put(session)
  } catch (err) {
    _openError = err instanceof Error ? err : new Error(String(err))
  }
}

export async function saveRep(rep: RepRecord): Promise<void> {
  const db = getDb()
  if (!db) return
  try {
    await db.reps.put(rep)
  } catch (err) {
    _openError = err instanceof Error ? err : new Error(String(err))
  }
}

export async function listRecentSessions(limit = 20): Promise<SessionRecord[]> {
  const db = getDb()
  if (!db) return []
  try {
    return await db.sessions
      .orderBy('startedAt')
      .reverse()
      .limit(limit)
      .toArray()
  } catch {
    return []
  }
}

/**
 * Bulk-fetch reps for a set of sessionIds, grouped by sessionId. Sessions in
 * `sessionIds` that have no reps still appear in the result with an empty
 * array — callers can rely on Map.get(id) returning [], not undefined.
 */
export async function listRepsForSessions(
  sessionIds: string[],
): Promise<Map<string, RepRecord[]>> {
  const out = new Map<string, RepRecord[]>()
  for (const id of sessionIds) out.set(id, [])
  if (sessionIds.length === 0) return out
  const db = getDb()
  if (!db) return out
  try {
    const reps = await db.reps.where('sessionId').anyOf(sessionIds).toArray()
    for (const r of reps) {
      const list = out.get(r.sessionId)
      if (list) list.push(r)
    }
  } catch {
    /* fall through with whatever was groupable */
  }
  return out
}

import { Suspense, lazy, useEffect, useState } from 'react'
import { useSession } from './store/session'
import {
  DEFAULT_SETTINGS,
  loadSettings,
  type SettingsRecord,
} from './store/settings'
import { IdleScreen } from './ui/IdleScreen'
import { TrainerScreen } from './ui/TrainerScreen'
import { SummaryScreen } from './ui/SummaryScreen'
import { SettingsScreen } from './ui/SettingsScreen'
import { AnalyticsScreen } from './ui/AnalyticsScreen'
import './App.css'

const PairScreen = lazy(() =>
  import('./ui/PairScreen').then((m) => ({ default: m.PairScreen })),
)

const ClipLibraryScreen = lazy(() =>
  import('./ui/ClipLibraryScreen').then((m) => ({
    default: m.ClipLibraryScreen,
  })),
)

type IdleView = 'idle' | 'settings' | 'analytics' | 'pair' | 'clips'

function App() {
  const phase = useSession((s) => s.phase)
  const [view, setView] = useState<IdleView>('idle')
  // Remember which view sent the user to pair so closing returns there.
  const [pairOpener, setPairOpener] = useState<'idle' | 'settings'>('settings')
  const [settings, setSettings] = useState<SettingsRecord>(DEFAULT_SETTINGS)

  useEffect(() => {
    void loadSettings().then(setSettings)
  }, [view])

  if (view === 'settings') {
    return (
      <SettingsScreen
        onClose={() => setView('idle')}
        onOpenPair={() => {
          setPairOpener('settings')
          setView('pair')
        }}
      />
    )
  }
  if (view === 'analytics') {
    return <AnalyticsScreen onClose={() => setView('idle')} />
  }
  if (view === 'clips') {
    return (
      <Suspense fallback={<div className="screen">Loading clip library…</div>}>
        <ClipLibraryScreen onClose={() => setView('idle')} />
      </Suspense>
    )
  }
  if (view === 'pair') {
    return (
      <Suspense fallback={<div className="screen">Loading pair UI…</div>}>
        <PairScreen onClose={() => setView(pairOpener)} />
      </Suspense>
    )
  }
  if (phase === 'idle')
    return (
      <IdleScreen
        onOpenSettings={() => setView('settings')}
        onOpenAnalytics={() => setView('analytics')}
        onOpenPair={() => {
          setPairOpener('idle')
          setView('pair')
        }}
        onOpenClips={() => setView('clips')}
      />
    )
  if (phase === 'ended') return <SummaryScreen />
  return (
    <TrainerScreen
      commitKeyCode={settings.commitKeyCode}
      commitKeyLabel={settings.commitKeyLabel}
    />
  )
}

export default App

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { getDb } from '../store/db'
import {
  addClip,
  deleteClip,
  getQuotaEstimate,
  isSoftWarnSize,
  listClips,
  quotaBanner,
} from './library'
import { CLIP_HARD_CAP_BYTES, CLIP_SOFT_WARN_BYTES } from './types'

function makeFile({
  name = 'clip.mp4',
  type = 'video/mp4',
  size = 5 * 1024 * 1024,
  content = 'abc',
}: {
  name?: string
  type?: string
  size?: number
  content?: string
} = {}): File {
  const file = new File([content], name, { type })
  if (size !== content.length) {
    Object.defineProperty(file, 'size', { value: size, configurable: true })
  }
  return file
}

async function clearClips() {
  const db = getDb()
  if (db) await db.clips.clear()
}

describe('addClip', () => {
  beforeEach(async () => {
    await clearClips()
  })

  it('persists a valid mp4 and returns { ok: true, clip }', async () => {
    const res = await addClip(makeFile({ name: 'demo.mp4', size: 2 * 1024 * 1024 }), {
      durationMs: 4500,
    })
    expect(res.ok).toBe(true)
    if (!res.ok) return
    expect(res.clip.name).toBe('demo.mp4')
    expect(res.clip.mimeType).toBe('video/mp4')
    expect(res.clip.durationMs).toBe(4500)
    expect(res.clip.sizeBytes).toBe(2 * 1024 * 1024)
    expect(res.clip.id).toMatch(/^clip-/)

    const db = getDb()
    const stored = await db?.clips.get(res.clip.id)
    expect(stored?.name).toBe('demo.mp4')
  })

  it('rejects an unsupported MIME type with reason: "unsupported-type"', async () => {
    const res = await addClip(makeFile({ type: 'text/plain', size: 1024 }), {
      durationMs: 0,
    })
    expect(res).toEqual({
      ok: false,
      reason: 'unsupported-type',
      message: expect.stringContaining('text/plain'),
    })
  })

  it('rejects a 250 MB blob with reason: "too-large"', async () => {
    const res = await addClip(makeFile({ size: 250 * 1024 * 1024 }), {
      durationMs: 10000,
    })
    expect(res.ok).toBe(false)
    if (res.ok) return
    expect(res.reason).toBe('too-large')
    expect(res.message).toContain('250 MB')
    expect(res.message).toContain('200 MB')
  })

  it('returns reason: "quota" when Dexie throws QuotaExceededError', async () => {
    const db = getDb()
    if (!db) throw new Error('db unavailable')
    const quotaErr = new DOMException('Quota exceeded', 'QuotaExceededError')
    const spy = vi.spyOn(db.clips, 'put').mockRejectedValueOnce(quotaErr)
    const res = await addClip(makeFile({ size: 1024 }), { durationMs: 100 })
    expect(res).toEqual({
      ok: false,
      reason: 'quota',
      message: expect.stringContaining('quota'),
    })
    spy.mockRestore()
  })

  it('returns reason: "storage-error" for a generic Dexie failure', async () => {
    const db = getDb()
    if (!db) throw new Error('db unavailable')
    const spy = vi
      .spyOn(db.clips, 'put')
      .mockRejectedValueOnce(new Error('disk i/o failed'))
    const res = await addClip(makeFile({ size: 1024 }), { durationMs: 100 })
    expect(res).toEqual({
      ok: false,
      reason: 'storage-error',
      message: 'disk i/o failed',
    })
    spy.mockRestore()
  })

  it('clamps a negative durationMs to 0', async () => {
    const res = await addClip(makeFile(), { durationMs: -50 })
    expect(res.ok).toBe(true)
    if (!res.ok) return
    expect(res.clip.durationMs).toBe(0)
  })
})

describe('listClips', () => {
  beforeEach(async () => {
    await clearClips()
  })

  it('returns clips in descending importedAt order', async () => {
    const db = getDb()
    if (!db) throw new Error('db unavailable')
    const baseBlob = new Blob(['x'], { type: 'video/mp4' })
    await db.clips.put({
      id: 'a',
      name: 'a.mp4',
      mimeType: 'video/mp4',
