      mimeType: 'video/mp4',
      durationMs: 1000,
      sizeBytes: 1,
      importedAt: 1000,
      blob: baseBlob,
    })
    await db.clips.put({
      id: 'b',
      name: 'b.mp4',
      mimeType: 'video/mp4',
      durationMs: 1000,
      sizeBytes: 1,
      importedAt: 3000,
      blob: baseBlob,
    })
    await db.clips.put({
      id: 'c',
