async function seedClip(page, { name = 'verify.mp4', durationMs = 5000 } = {}) {
  await page.evaluate(
    async ({ name, durationMs }) => {
      const dbReq = indexedDB.open('pointfight-reactor', 4)
      const db = await new Promise((resolve, reject) => {
        dbReq.onsuccess = () => resolve(dbReq.result)
        dbReq.onerror = () => reject(dbReq.error)
        dbReq.onupgradeneeded = () => {
          /* upgrade is handled by Dexie on first app load; this is just a read-side opener */
        }
      })
      const tx = db.transaction(['clips'], 'readwrite')
      const store = tx.objectStore('clips')
      const blob = new Blob([new Uint8Array(1024)], { type: 'video/mp4' })
      const id = `clip-verify-${Date.now()}`
      await new Promise((resolve, reject) => {
        const req = store.put({
          id,
          name,
          mimeType: 'video/mp4',
          durationMs,
          sizeBytes: blob.size,
          importedAt: Date.now(),
          blob,
        })
        req.onsuccess = () => resolve()
        req.onerror = () => reject(req.error)
      })
      await new Promise((r) => (tx.oncomplete = r))
      db.close()
      return id
    },
    { name, durationMs },
  )
}

