1	import type { CueId } from '../engine/types'
2	import { getDb } from '../store/db'
3	import {
4	  CLIP_HARD_CAP_BYTES,
5	  CLIP_SOFT_WARN_BYTES,
6	  SUPPORTED_CLIP_MIME_TYPES,
7	  type AddClipResult,
8	  type ClipRecord,
9	} from './types'
10	
11	function mintClipId(now: number): string {
12	  return `clip-${now.toString(36)}-${Math.random().toString(36).slice(2, 9)}`
13	}
14	
15	function isQuotaError(err: unknown): boolean {
16	  return (
17	    err instanceof DOMException &&
18	    (err.name === 'QuotaExceededError' || err.code === 22)
19	  )
20	}
21	
22	function errorMessage(err: unknown): string {
23	  if (err instanceof Error) return err.message
24	  return String(err)
25	}
26	
27	export async function addClip(
28	  file: File,
29	  opts: { durationMs: number },
30	): Promise<AddClipResult> {
31	  const db = getDb()
32	  if (!db) {
33	    return {
34	      ok: false,
35	      reason: 'storage-error',
36	      message: 'Database is unavailable.',
37	    }
38	  }
39	
40	  if (!SUPPORTED_CLIP_MIME_TYPES.includes(file.type)) {
41	    return {
42	      ok: false,
43	      reason: 'unsupported-type',
44	      message: `File type ${file.type || '(unknown)'} is not supported. Use .mp4.`,
45	    }
46	  }
47	
48	  if (file.size > CLIP_HARD_CAP_BYTES) {
49	    const mb = Math.round(file.size / 1024 / 1024)
50	    return {
51	      ok: false,
52	      reason: 'too-large',
53	      message: `Clip is ${mb} MB; the per-clip limit is ${CLIP_HARD_CAP_BYTES / 1024 / 1024} MB.`,
54	    }
55	  }
56	
57	  const clip: ClipRecord = {
58	    id: mintClipId(Date.now()),
59	    name: file.name,
60	    mimeType: file.type,
61	    durationMs: Math.max(0, Math.round(opts.durationMs)),
62	    sizeBytes: file.size,
63	    importedAt: Date.now(),
64	    blob: file,
65	  }
66	
67	  try {
68	    await db.clips.put(clip)
69	  } catch (err) {
70	    if (isQuotaError(err)) {
71	      return {
72	        ok: false,
73	        reason: 'quota',
74	        message:
75	          'Browser storage quota exceeded. Delete a clip before importing more.',
76	      }
77	    }
78	    return { ok: false, reason: 'storage-error', message: errorMessage(err) }
79	  }
80	
81	  return { ok: true, clip }
82	}
83	
84	export async function listClips(): Promise<ClipRecord[]> {
85	  const db = getDb()
86	  if (!db) return []
87	  try {
88	    return await db.clips.orderBy('importedAt').reverse().toArray()
89	  } catch {
90	    return []
91	  }
92	}
93	
94	export async function getClip(id: string): Promise<ClipRecord | null> {
95	  const db = getDb()
96	  if (!db) return null
97	  try {
98	    return (await db.clips.get(id)) ?? null
99	  } catch {
100	    return null
101	  }
102	}
103	
104	/**
105	 * Writes a single `(cueId, cueAtMs)` tag onto an existing clip in place.
106	 * Returns the updated row, or `null` when the clip does not exist or the
107	 * DB is unavailable. `cueAtMs` is clamped to `[0, durationMs]` so tagging
108	 * past the end of the clip is impossible.
109	 *
110	 * Per the Phase 6 decision memo §2: one tag per clip; edits overwrite —
111	 * there is no version history. The columns are not indexed (see
112	 * `db.ts:34-40`'s v4 schema declares neither `cueId` nor `cueAtMs` as
113	 * keys), so this is a blob-internal update and does not require a Dexie
114	 * version bump.
115	 */
116	export async function updateClipTag(
117	  id: string,
118	  tag: { cueId: CueId; cueAtMs: number },
119	): Promise<ClipRecord | null> {
120	  const db = getDb()
121	  if (!db) return null
122	  try {
123	    const existing = await db.clips.get(id)
124	    if (!existing) return null
125	    const clamped = Math.max(
126	      0,
127	      Math.min(Math.round(tag.cueAtMs), existing.durationMs),
128	    )
129	    const updated: ClipRecord = {
130	      ...existing,
131	      cueId: tag.cueId,
132	      cueAtMs: clamped,
133	    }
134	    await db.clips.put(updated)
135	    return updated
136	  } catch {
137	    return null
138	  }
139	}
140	
141	export async function deleteClip(id: string): Promise<void> {
142	  const db = getDb()
143	  if (!db) return
144	  try {
145	    await db.clips.delete(id)
146	  } catch {
147	    /* leave the row in place; UI can retry */
148	  }
149	}
150	
151	export interface QuotaEstimate {
152	  usageBytes: number
153	  quotaBytes: number
154	  /** 0..1; quotaBytes can be 0 on browsers that decline to report. */
155	  percent: number
156	}
157	
158	export async function getQuotaEstimate(): Promise<QuotaEstimate | null> {
159	  if (typeof navigator === 'undefined' || !navigator.storage?.estimate) {
160	    return null
161	  }
162	  try {
163	    const est = await navigator.storage.estimate()
164	    const usage = est.usage ?? 0
165	    const quota = est.quota ?? 0
166	    return {
167	      usageBytes: usage,
168	      quotaBytes: quota,
169	      percent: quota > 0 ? usage / quota : 0,
170	    }
171	  } catch {
172	    return null
173	  }
174	}
175	
176	export function isSoftWarnSize(bytes: number): boolean {
177	  return bytes > CLIP_SOFT_WARN_BYTES && bytes <= CLIP_HARD_CAP_BYTES
178	}
179	
180	export function quotaBanner(estimate: QuotaEstimate | null): 'none' | 'warn' | 'cap' {
181	  if (!estimate) return 'none'
182	  if (estimate.percent > 0.95) return 'cap'
183	  if (estimate.percent > 0.8) return 'warn'
184	  return 'none'
185	}
